{
  "claims": [
    {
      "claim_text": "Once gc.auto or gc.autoPackLimit triggers housekeeping, the other tasks such as reflog and rerere pruning run as well.",
      "verdict": "SUPPORTED",
      "reasoning": "Passage 0 states that once housekeeping is triggered by exceeding limits of gc.auto and gc.autoPackLimit, all other housekeeping tasks (e.g. rerere, working trees, reflog) will be performed as well.",
      "citations": [
        {
          "index": 0,
          "quote": "Once housekeeping is triggered by exceeding the limits of configuration options such as gc.auto and gc.autoPackLimit, all other housekeeping tasks (e.g. rerere, working trees, reflog…​) will be performed as well."
        }
      ]
    },
    {
      "claim_text": "With gc.auto set to 0, git gc --auto never consolidates packs, whatever gc.autoPackLimit says.",
      "verdict": "SUPPORTED",
      "reasoning": "Passage 2 says setting gc.auto to 0 disables automatic packing and any other heuristic including gc.autoPackLimit. Passage 3 also says setting gc.auto to 0 will also disable gc.autoPackLimit.",
      "citations": [
        {
          "index": 2,
          "quote": "Setting this to 0 disables not only automatic packing based on the number of loose objects, but also any other heuristic git gc --auto will otherwise use to determine if there’s work to do, such as gc.autoPackLimit."
        },
        {
          "index": 3,
          "quote": "Setting gc.auto to 0 will also disable this."
        }
      ]
    },
    {
      "claim_text": "gc.bigPackThreshold defaults to 1 GB.",
      "verdict": "CONTRADICTED",
      "reasoning": "Passage 4 states that gc.bigPackThreshold defaults to zero, not 1 GB.",
      "citations": [
        {
          "index": 4,
          "quote": "Defaults to zero."
        }
      ]
    },
    {
      "claim_text": "gc.bigPackThreshold keeps every non-cruft pack above the limit.",
      "verdict": "SUPPORTED",
      "reasoning": "Passage 4 says if non-zero, all non-cruft packs larger than this limit are kept when git gc is run.",
      "citations": [
        {
          "index": 4,
          "quote": "If non-zero, all non-cruft packs larger than this limit are kept when git gc is run."
        }
      ]
    },
    {
      "claim_text": "gc.bigPackThreshold is ignored when the number of kept packs exceeds gc.autoPackLimit.",
      "verdict": "SUPPORTED",
      "reasoning": "Passage 5 states that if the number of kept packs is more than gc.autoPackLimit, this configuration variable is ignored.",
      "citations": [
        {
          "index": 5,
          "quote": "Note that if the number of kept packs is more than gc.autoPackLimit, this configuration variable is ignored"
        }
      ]
    },
    {
      "claim_text": "gc.autoPackLimit defaults to 50.",
      "verdict": "SUPPORTED",
      "reasoning": "Passage 3 states the default value of gc.autoPackLimit is 50.",
      "citations": [
        {
          "index": 3,
          "quote": "The default value is 50."
        }
      ]
    },
    {
      "claim_text": "If gc.bigPackThreshold is not set and the memory git repack needs is not available, the largest pack is excluded from repacking.",
      "verdict": "SUPPORTED",
      "reasoning": "Passage 6 states that if the amount of memory estimated for git repack to run smoothly is not available and gc.bigPackThreshold is not set, the largest pack will also be excluded.",
      "citations": [
        {
          "index": 6,
          "quote": "If the amount of memory estimated for git repack to run smoothly is not available and gc.bigPackThreshold is not set, the largest pack will also be excluded"
        }
      ]
    },
    {
      "claim_text": "When cruft packs are used, both the prune step and the cruft expiration use a two-week grace period by default.",
      "verdict": "SUPPORTED",
      "reasoning": "Passage 7 states that git gc will call prune --expire 2.weeks.ago and repack --cruft --cruft-expiration 2.weeks.ago if using cruft packs.",
      "citations": [
        {
          "index": 7,
          "quote": "When git gc is run, it will call prune --expire 2.weeks.ago (and repack --cruft --cruft-expiration 2.weeks.ago if using cruft packs via gc.cruftPacks or --cruft)."
        }
      ]
    },
    {
      "claim_text": "Setting gc.pruneExpire to now removes that grace period, which raises the risk of corruption when another process is writing to the repository.",
      "verdict": "SUPPORTED",
      "reasoning": "Passage 7 says the value 'now' may be used to disable this grace period and always prune unreachable objects immediately, and mentions this feature helps prevent corruption when git gc runs concurrently with another process. Passage 8 explicitly says --prune=now prunes loose objects regardless of age and increases the risk of corruption if another process is writing concurrently.",
      "citations": [
        {
          "index": 7,
          "quote": "The value \"now\" may be used to disable this grace period and always prune unreachable objects immediately"
        },
        {
          "index": 8,
          "quote": "--prune=now prunes loose objects regardless of their age and increases the risk of corruption if another process is writing to the repository concurrently"
        }
      ]
    }
  ]
}
